import { useEffect, useState } from "react";
import axios from "axios";

function Buy() {
  const [foods, setFoods] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:5000/foods")
      .then(res => setFoods(res.data));
  }, []);

 return (
  <div>
    <h2>Foods</h2>

    {foods.map((food) => (
      <div key={food._id}>
        <img src={food.image} alt="food" width="200" />
        <h3>{food.name}</h3>
      </div>
    ))}
  </div>
);
}

export default Buy;
